// Only unprocessed rows with enough substance to be worth a model call.
// Without the status check this reprocesses the whole sheet every six hours,
// which is a bill that grows quietly until someone notices.
const out = [];
for (const item of $input.all()) {
  const r = item.json;
  if (String(r.status ?? '').trim().toLowerCase() === 'done') continue;
  const body = String(r.body ?? '').trim();
  if (body.length < 200) continue;   // too thin to repurpose into anything useful
  out.push({ json: { rowId: r.rowId ?? r.id, title: String(r.title ?? '').trim(), body: body.slice(0, 6000) } });
}
return out.slice(0, 5);   // cap per run, so a 300-row backlog cannot fire 300 calls at once

// Never trust the model to have obeyed the character limits. It will exceed
// them, and a caption rejected by the platform at publish time is a failure
// nobody sees until the slot is missed. Truncate on a word boundary here.
const LIMITS = { instagram: 300, linkedin: 600, tiktok: 150 };
const clip = (s, n) => {
  s = String(s ?? '').trim();
  if (s.length <= n) return s;
  const cut = s.slice(0, n);
  return cut.slice(0, Math.max(cut.lastIndexOf(' '), n - 20)).trim();
};
const out = [];
const sources = $('Unprocessed and substantial').all();
$input.all().forEach((item, i) => {
  const src = sources[i]?.json ?? {};
  let v = {};
  try {
    const raw = item.json.message?.content ?? item.json.content ?? item.json;
    v = typeof raw === 'string' ? JSON.parse(raw) : raw;
  } catch (e) { v = {}; }
  const instagram = clip(v.instagram, LIMITS.instagram);
  const linkedin  = clip(v.linkedin,  LIMITS.linkedin);
  const tiktok    = clip(v.tiktok,    LIMITS.tiktok);
  // A blank platform means the model failed. Flag for review rather than
  // writing an empty caption into the calendar and calling it done.
  const incomplete = !instagram || !linkedin || !tiktok;
  out.push({ json: {
    rowId: src.rowId, title: src.title,
    instagram, linkedin, tiktok,
    hashtags: Array.isArray(v.hashtags) ? v.hashtags.slice(0, 6).join(' ') : '',
    status: incomplete ? 'needs review' : 'done',
    generatedAt: new Date().toISOString()
  }});
});
return out;
